examples.template:
MonarchFormField({{label}}, helper: {{description}}) {
    MonarchRangeSlider(
        {{label}},
        value: $price,
        in: {{min|double}}...{{max|double}},
        step: {{step|double}},
        valueText: { {{valuePrefix}} + String(Int($0)) },
        showsValue: true
    )
}

examples.code:
MonarchFormField("Price", helper: "Results update when you let go.") {
    MonarchRangeSlider(
        "Price",
        value: $price,
        in: 0.0...1000.0,
        step: 50.0,
        valueText: { "$" + String(Int($0)) },
        showsValue: true
    )
}
